const $=s=>document.querySelector(s);const el=(t,c,h)=>{const e=document.createElement(t);if(c)e.className=c;if(h!==undefined)e.innerHTML=h;return e};
const esc=s=>String(s).replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));
const reduced=()=>{try{return matchMedia('(prefers-reduced-motion: reduce)').matches}catch(e){return false}};
const SETKEY='aegis2-settings';function loadSettings(){try{Object.assign(UI,JSON.parse(localStorage.getItem(SETKEY)||'{}'))}catch(e){}}function saveSettings(){try{localStorage.setItem(SETKEY,JSON.stringify({zoom:UI.zoom,dpad:UI.dpad,music:AU.music,sfx:AU.sfx,vol:AU.vol,mini:UI.mini}))}catch(e){}}
const ZOOMS=[9,11,13,15,19,23,29];
function sizeMap(){const box=$('#mapbox');const cv=$('#map');if(!box||!cv)return;const w=box.clientWidth,h=box.clientHeight;if(!w||!h)return;const dpr=Math.min(2,devicePixelRatio||1);const desk=w>700;let zi=UI.zoom||0;const base=desk?4:1;const cols=ZOOMS[clamp(base+zi,0,ZOOMS.length-1)];let T=Math.floor(w/cols);const rows=Math.max(7,Math.ceil(h/T));UI.cols=cols;UI.rows=rows;UI.tile=Math.round(T*dpr);cv.width=UI.tile*cols;cv.height=UI.tile*rows;cv.style.width=T*cols+'px';cv.style.height=T*rows+'px';const mc=$('#mini');if(mc){const ms=desk?176:92;mc.width=mc.height=Math.round(ms*dpr);mc.style.width=mc.style.height=ms+'px';mc.hidden=!UI.mini}draw()}
function pullFx(){const now=performance.now();RT.fxq.forEach(f=>{f.until=now+(f.type==='boom'?320:190);UI.fx.push(f);if(f.type==='boom')sfx('boom');else if(f.type==='shot')sfx('gun');else if(f.type==='bolt')sfx('spell');else if(f.type==='slash')sfx('hit')});RT.fxq.length=0}
const MOONICON=['●','◔','◑','◕','○','◕','◑','◔'];
function refresh(){if(!G||!G.p)return;pullFx();if(G.over){showEnd();return}const p=G.p,se=seasonIdx();document.documentElement.dataset.season=se;
 const bar=(id,v,m,txt,show)=>{const e=$('#m-'+id);if(!e)return;e.hidden=show===false;e.querySelector('i').style.width=clamp(v/m*100,0,100)+'%';e.querySelector('b').textContent=txt;e.classList.toggle('low',v/m<.25)};
 bar('hp',p.hp,p.mh,'♥ '+p.hp+'/'+p.mh);bar('mp',p.mp,p.mmp,'✦ '+p.mp+'/'+p.mmp);bar('fd',isVamp()?(p.blood??0):p.hunger,100,isVamp()?'Blood '+Math.round(p.blood??0):'Food '+Math.round(p.hunger));bar('wt',p.thirst,100,'Water '+Math.round(p.thirst));bar('ch',p.charge||0,100,'☀ '+Math.round(p.charge||0),!!augOn());
 const t=$('#m-tp');t.querySelector('b').textContent=p.temp<-55?'Freezing':p.temp<-25?'Cold':p.temp>55?'Scorching':p.temp>25?'Hot':'Mild';t.classList.toggle('low',Math.abs(p.temp)>55);t.querySelector('i').style.width=clamp((p.temp+100)/2,2,100)+'%';
 $('#when').textContent=SEASONS[se]+' '+dayNum()+' · '+timeName();$('#moon').textContent=MOONICON[moonPhase()];$('#moon').title=moonName();
 const site=L.world?nearSite(p.x,p.y,0):null;$('#where').textContent=(site&&site.known?site.name+' · ':'')+(L.world?BIOMEN[regionAt(p.x,p.y)]:(L.id.startsWith('vault')?'Precursor vault':'Underground'))+' · '+WXN[G.wx.k];
 $('#who').textContent=p.name+' · Lv '+p.lvl+' · '+p.coins+'¢';
 const b=$('#badges');b.innerHTML='';const add=(s,c)=>b.appendChild(el('span','bdg '+(c||''),esc(s)));if(p.sneak)add('Sneaking','ok');if(p.mount)add('Riding '+MOUNTS[p.mount.s].n,'ok');if(p.aboard)add('Aboard '+vesselById(p.aboard).kind+' '+vesselById(p.aboard).hp+'/'+vesselById(p.aboard).mh,'ok');p.dz.forEach(z=>{if(z.inc>0)return;add(dzName(z),'bad')});if(p.fx.poison)add('Poisoned','bad');if(p.burning>0)add('Burning','bad');if(p.dom>0)add('Mind seized','bad');if(p.breath>10)add('Drowning '+p.breath,'bad');if(p.fx.wet)add('Wet');if(p.torch>0)add('Torch');if(p.fx.invis)add('Invisible','ok');if(p.fx.absorb)add('Warded','ok');if(p.fx.waterwalk)add('Water-walking','ok');if(p.fx.wolf)add('Wolf form','bad');if(p.inspired)add('Inspired','ok');if(p.pts>0)add(p.pts+' stat point','ok');if(bloodMoon()&&isNight())add('Blood moon','bad');if(eclipse())add('Eclipse','bad');
 const lg=$('#log');const items=G.log.slice(-40);lg.innerHTML=items.map(m=>`<p class="${m.c}">${esc(m.t)}</p>`).join('');lg.scrollTop=lg.scrollHeight;$('#sneakbtn').classList.toggle('on',p.sneak);renderQuick();
 if(RT.seasonBanner){showSeason(RT.seasonBanner);RT.seasonBanner=null}if(G.log.length!==UI.lastLog){const last=G.log[G.log.length-1];if(last){if(/level/i.test(last.t)&&last.c==='good')sfx('level');else if(last.c==='bad'&&/hits you|bite|burn/i.test(last.t))sfx('hurt');else if(/coins/.test(last.t))sfx('coin');else if(/howl/i.test(last.t))sfx('howl')}UI.lastLog=G.log.length}draw()}
function showSeason(a){const b=$('#banner');b.hidden=false;b.innerHTML=`<h2>${a.t}</h2><p>${esc(a.hd)}</p><ul>${a.l.slice(0,3).map(s=>'<li>'+esc(s)+'</li>').join('')}</ul><button id="bannerok" class="btn pri">Carry on</button>`;$('#bannerok').onclick=()=>{b.hidden=true}}
// ---- quickslots
function renderQuick(){const q=$('#quick');if(!q)return;q.innerHTML='';const p=G.p;p.quick=p.quick||[];for(let i=0;i<4;i++){const k=p.quick[i];const it=k&&p.inv.find(x=>(x.k+(x.pt||''))===k);const b=el('button','qs'+(it?'':' empty'));if(it){const c=document.createElement('canvas');c.width=c.height=18;const x=c.getContext('2d');x.fillStyle=itemColor(it);x.beginPath();x.arc(9,9,7,0,7);x.fill();b.appendChild(c);b.appendChild(el('span','',esc(shortName(it))))}else b.appendChild(el('span','','Slot '+(i+1)));b.title=it?iname(it):'Long-press an item in your pack to assign';b.onclick=()=>{if(it){if(idef(it).k==='throw'){setTarget('Tap a tile to throw '+idef(it).n.toLowerCase()+'.',(x,y)=>doThrow(it,x,y))}else{useItem(it);refresh()}}else packScreen()};q.appendChild(b)}}
function shortName(it){const n=it.k==='potion'?potionLabel(it):iname(it);return n.length>12?n.slice(0,11)+'…':n}
// ---- sheets
function closeSheet(){$('#sheet').hidden=true;$('#sheet').innerHTML=''}
function showSheet(s){sfx('ui');const sh=$('#sheet');sh.hidden=false;sh.innerHTML='';const box=el('div','sheetbox');const h=el('div','sheethd');h.appendChild(el('h3','',esc(s.title||'')));const x=el('button','closex','Close');x.onclick=()=>{closeSheet();refresh()};h.appendChild(x);box.appendChild(h);if(s.text){const parts=String(s.text).split('\n');parts.forEach(t=>{const m=t.match(/^([^:"]{1,40}): "(.*)"$/);if(m){const q=el('div','say');q.appendChild(el('b','',esc(m[1])));q.appendChild(el('span','','“'+esc(m[2])+'”'));box.appendChild(q)}else if(t.trim())box.appendChild(el('p','sheettxt',esc(t)))})}if(s.html)box.appendChild(s.html);const list=el('div','opts');(s.options||[]).forEach(o=>{if(o.label==='Close'||o.label==='Leave')return;const b=el('button','opt '+(o.cls||''),`<span>${esc(o.label)}</span>`+(o.sub?`<small>${esc(o.sub)}</small>`:''));if(o.disabled)b.disabled=true;b.onclick=()=>handle(o.fn());list.appendChild(b)});const lv=(s.options||[]).find(o=>o.label==='Leave');if(lv){const b=el('button','opt ghost','<span>Leave</span>');b.onclick=()=>handle(lv.fn());list.appendChild(b)}box.appendChild(list);sh.appendChild(box);sh.onclick=e=>{if(e.target===sh){closeSheet();refresh()}};const f=list.querySelector('button:not([disabled])');if(f&&!('ontouchstart' in window))f.focus({preventScroll:true})}
const KEEP={keep:1};
function handle(r){if(r===KEEP)return;if(G&&G.over){closeSheet();refresh();return}if(!r){closeSheet();refresh();return}if(r.options||r.html){showSheet(r);refresh();return}if(r.walk){closeSheet();startWalk(r.walk.x,r.walk.y);return}if(r.screen){closeSheet();({forge:forgeScreen,spellforge:spellScreen,brew:brewScreen})[r.screen]();return}if(r.sheet){showSheet(r.sheet);refresh();return}if(r.tile){showSheet(actionSheetFor(r.tile.x,r.tile.y));return}closeSheet();refresh()}
// ---- walking
function pathTo(x,y){const p=G.p;const lim=6000;const q=[[p.x,p.y]];const prev=new Map();prev.set(IX(p.x,p.y),-1);let h=0;const goal=IX(x,y);const sail=!!p.aboard;while(h<q.length&&h<lim){const[a,b]=q[h++];if(IX(a,b)===goal)break;for(const[dx,dy]of DIRS){const nx=a+dx,ny=b+dy;if(!inb(L,nx,ny)||Math.abs(nx-p.x)>45||Math.abs(ny-p.y)>45)continue;const k=IX(nx,ny);if(prev.has(k)||!seenAt(nx,ny))continue;const d=tdef(nx,ny);const ok=sail?(d.water||d.swim)&&!d.icy:(d.p&&!d.swim||d.k==='door');if(!ok&&k!==goal)continue;if(L.fire[k]||d.trap&&k!==goal||d.lava)continue;prev.set(k,IX(a,b));q.push([nx,ny])}}if(!prev.has(goal))return null;const path=[];let u=goal;while(u!==-1&&u!==IX(p.x,p.y)){path.unshift({x:u%L.w,y:Math.floor(u/L.w)});u=prev.get(u)}return path}
function startWalk(x,y){const path=pathTo(x,y);if(!path||!path.length){msg('You cannot see a way there.','hint');refresh();return}UI.walking={path,seen:hostilesSeen(),lvl:L.id};stepWalk()}
function hostilesSeen(){return new Set(RT.act.filter(c=>RT.vis.has(IX(c.x,c.y))&&hostile(c,G.p)&&!c.hidden).map(c=>c.id))}
function stepWalk(){if(!UI.walking||!G||G.over){UI.walking=null;return}const w=UI.walking;const s=w.path.shift();if(!s){UI.walking=null;refresh();return}const dx=s.x-G.p.x,dy=s.y-G.p.y;if(Math.abs(dx)>1||Math.abs(dy)>1||(at(s.x,s.y)&&!isP(at(s.x,s.y)))){UI.walking=null;refresh();return}const hp=G.p.hp;const r=actMove(dx,dy);if(r){UI.walking=null;handle(r);return}if(!G.p.aboard&&UI.frame%2===0)sfx('step');const now=hostilesSeen();let stop=G.p.hp<hp||L.id!==w.lvl||RT.seasonBanner;now.forEach(i=>{if(!w.seen.has(i))stop=true});refresh();if(stop){if(G.p.hp>=hp&&!RT.seasonBanner)msg('You stop. Something is near.','warn');UI.walking=null;refresh();return}setTimeout(stepWalk,reduced()?15:60)}
// ---- input
function tileFromEvent(e){const cv=$('#map');const r=cv.getBoundingClientRect();const T=r.width/UI.cols;const i=Math.floor((e.clientX-r.left)/T),j=Math.floor((e.clientY-r.top)/T);const{vx,vy}=view();return{x:vx+i,y:vy+j}}
function plainWalkable(x,y){const k=IX(x,y),d=tdef(x,y);if(!seenAt(x,y))return false;if(G.p.aboard)return(d.water||d.swim)&&!at(x,y)&&!d.icy;if(!d.p||d.swim)return false;if(at(x,y)||vesselAt(x,y))return false;if(L.items[k]||L.crops[k]||L.fire[k]||d.link||d.bed||d.k==='soil'||d.forage||d.k==='bush'||d.sacred||d.lava)return false;return true}
function bindMap(){const cv=$('#map');let tm=null,long=false,start=null,pinch=null;cv.addEventListener('pointerdown',e=>{audioInit();if(UI.walking){UI.walking=null;return}long=false;start=e;tm=setTimeout(()=>{long=true;const t=tileFromEvent(start);if(inb(L,t.x,t.y)&&!UI.target&&!UI.build)showSheet(actionSheetFor(t.x,t.y))},420)});cv.addEventListener('pointerup',e=>{clearTimeout(tm);if(long||pinch)return;onTap(tileFromEvent(e))});cv.addEventListener('pointerleave',()=>clearTimeout(tm));cv.addEventListener('contextmenu',e=>{e.preventDefault();const t=tileFromEvent(e);if(inb(L,t.x,t.y))showSheet(actionSheetFor(t.x,t.y))});cv.addEventListener('wheel',e=>{e.preventDefault();zoomBy(e.deltaY>0?1:-1)},{passive:false});
 cv.addEventListener('touchstart',e=>{if(e.touches.length===2){clearTimeout(tm);pinch={d:Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY)}}},{passive:true});cv.addEventListener('touchmove',e=>{if(pinch&&e.touches.length===2){const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);if(Math.abs(d-pinch.d)>40){zoomBy(d<pinch.d?1:-1);pinch.d=d}}},{passive:true});cv.addEventListener('touchend',()=>{setTimeout(()=>pinch=null,50)})}
function zoomBy(n){UI.zoom=clamp((UI.zoom||0)+n,-1,3);saveSettings();sizeMap()}
function onTap(t){if(!G||G.over||!inb(L,t.x,t.y))return;if(UI.target){const f=UI.target.fn;UI.target=null;$('#hint').hidden=true;f(t.x,t.y);refresh();return}if(UI.build){buildAt(UI.build,t.x,t.y);const b=UI.build;if(!canBuild(b))UI.build=null,$('#hint').hidden=true;refresh();return}const p=G.p;if(t.x===p.x&&t.y===p.y){showSheet(actionSheetFor(t.x,t.y));return}const e=at(t.x,t.y);if(e&&RT.vis.has(IX(t.x,t.y))&&!(e.hidden&&dist(e.x,e.y,p.x,p.y)>1)){if(dist(e.x,e.y,p.x,p.y)===1&&hostile(e,p)){handle(actMove(t.x-p.x,t.y-p.y));return}showSheet(actionSheetFor(t.x,t.y));return}if(plainWalkable(t.x,t.y)){if(dist(p.x,p.y,t.x,t.y)===1)handle(actMove(t.x-p.x,t.y-p.y));else startWalk(t.x,t.y);return}if(vesselAt(t.x,t.y)&&dist(p.x,p.y,t.x,t.y)===1){handle(actMove(t.x-p.x,t.y-p.y));return}showSheet(actionSheetFor(t.x,t.y))}
function canBuild(k){return Object.entries(BUILD[k].need).every(([m,q])=>count(m)>=q)}
function setHint(text){$('#hint').innerHTML='<span>'+esc(text)+'</span> <button id="hintx" class="btn sm">Cancel</button>';$('#hintx').onclick=()=>{UI.target=null;UI.build=null;$('#hint').hidden=true;refresh()};$('#hint').hidden=false}
function setTarget(prompt,fn){closeSheet();UI.target={prompt,fn};setHint(prompt);refresh()}
function move(dx,dy){if(!G||G.over)return;UI.walking=null;if(!$('#sheet').hidden)return;audioInit();const r=actMove(dx,dy);handle(r);if(!r&&!G.p.aboard)sfx('step')}
function bindControls(){document.querySelectorAll('[data-d]').forEach(b=>{const[dx,dy]=b.dataset.d.split(',').map(Number);b.addEventListener('click',()=>move(dx,dy))});$('#here').onclick=()=>{if(G&&!G.over)showSheet(actionSheetFor(G.p.x,G.p.y))};$('#sneakbtn').onclick=()=>{toggleSneak();refresh()};$('#waitbtn').onclick=()=>{actWait();refresh()};$('#packbtn').onclick=packScreen;$('#magicbtn').onclick=magicScreen;$('#craftbtn').onclick=craftScreen;$('#buildbtn').onclick=buildScreen;$('#menubtn').onclick=menuScreen;$('#mapbtn').onclick=mapScreen;$('#log').onclick=logScreen;$('#zin').onclick=()=>zoomBy(-1);$('#zout').onclick=()=>zoomBy(1);$('#minitog').onclick=()=>{UI.mini=!UI.mini;saveSettings();sizeMap()};
 document.addEventListener('keydown',e=>{if(!G||G.over||$('#game').hidden)return;if(e.target&&(e.target.tagName==='INPUT'||e.target.tagName==='SELECT'))return;audioInit();const open=!$('#sheet').hidden;if(e.key==='Escape'){closeSheet();UI.target=null;UI.build=null;$('#hint').hidden=true;refresh();return}if(open){if(/^[1-9]$/.test(e.key)){const bs=[...$('#sheet').querySelectorAll('.opt:not([disabled])')].filter(b=>b.offsetParent!==null);const b=bs[+e.key-1];if(b){e.preventDefault();b.click()}}return}const m={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0],k:[0,-1],j:[0,1],h:[-1,0],l:[1,0],y:[-1,-1],u:[1,-1],b:[-1,1],n:[1,1],'8':[0,-1],'2':[0,1],'4':[-1,0],'6':[1,0],'7':[-1,-1],'9':[1,-1],'1':[-1,1],'3':[1,1]}[e.key];if(m){e.preventDefault();move(m[0],m[1]);return}const a={'.':()=>{actWait();refresh()},'5':()=>{actWait();refresh()},' ':()=>$('#here').click(),i:packScreen,m:magicScreen,c:craftScreen,B:buildScreen,s:()=>{toggleSneak();refresh()},M:mapScreen,J:journalScreen,C:charScreen,'?':helpScreen,'+':()=>zoomBy(-1),'=':()=>zoomBy(-1),'-':()=>zoomBy(1),L:legendsScreen,F:()=>{const w=DIRS.map(([a,b])=>({x:G.p.x+a,y:G.p.y+b})).find(q=>canFishAt(q.x,q.y));if(w){fish(w.x,w.y);refresh()}}}[e.key];if(a){e.preventDefault();a()}})}
// ---- screens
function describeItem(it){const d=idef(it);const b=[];if(it.k==='potion')return G.alch.idPot[it.pt]?'Potion of '+APNAME[it.pt]+'.':'An unidentified potion. Drink it, throw it, or have a healer identify it.';if(it.k==='brew')return'Brewed: '+(d.fx.length?d.fx.map(f=>APNAME[f]).join(', '):'sludge')+'. Strength '+d.mag+'.';if(REAGENTS.includes(it.k)){const kn=G.alch.known[it.k]||[];b.push('Alchemy: '+(kn.length?kn.map(f=>APNAME[f]).join(', '):'unknown properties')+(kn.length<4?' (taste to learn more)':''))}if(d.k==='wpn'){b.push('Damage '+d.d);if(d.rng)b.push('Range '+d.rng);if(d.st)b.push('Uses '+STATN[d.st]);if(d.mercy)b.push('Never kills');if(d.quiet)b.push('Quiet');if(d.lance)b.push('Lance: big bonus mounted')}if(d.k==='arm'){b.push('Armor '+(d.ar||0));if(d.warm)b.push('Warm');if(d.cool)b.push('Cool');if(d.noisy)b.push('Noisy');if(d.disg)b.push('Disguise: '+FAC[d.disg].n)}if(d.req)b.push('Needs '+Object.entries(d.req).map(([k,v])=>STATN[k]+' '+v).join(', '));if(d.ench)b.push(FENCH[d.ench].d);if(d.hun)b.push('Food +'+d.hun);if(d.thi)b.push('Water +'+d.thi);if(d.hp)b.push('Heals '+d.hp);if(d.boost)b.push('Boosts '+STATN[d.boost]);if(d.spike)b.push('Slip into a drink');if(d.effect)b.push('Thrown');if(d.crop)b.push('Plant on tilled soil');if(d.fishing)b.push('Fishing tool');if(it.k==='shard')b.push('A shard of the seal. '+shardsHeld()+' of '+shardsNeeded()+'.');return b.join(' · ')}
function packScreen(){const p=G.p;const box=el('div','pack');const groups={};p.inv.forEach(it=>{const cat=ICAT[idef(it).k]||'Other';(groups[cat]=groups[cat]||[]).push(it)});box.appendChild(el('p','sheettxt',p.coins+' coins · '+p.inv.length+'/'+packCap()+' slots'+(idef(p.eq.w).gun?' · '+(p.loaded?'Loaded':'Unloaded')+', '+count('shot')+' shots':'')+(idef(p.eq.w).bow?' · '+count('arrow')+' arrows':'')));Object.keys(groups).sort().forEach(cat=>{box.appendChild(el('h4','',cat));groups[cat].forEach(it=>{const eq=it===p.eq.w||it===p.eq.a;const b=el('button','opt'+(eq?' pri':''),`<span>${eq?'⚔ ':''}${esc(it.k==='potion'?potionLabel(it)+((it.q||1)>1?' ×'+it.q:''):it.k==='brew'?idef(it).n:iname(it))}</span><small>${esc(describeItem(it))}</small>`);b.onclick=()=>itemSheet(it);box.appendChild(b)})});showSheet({title:'Pack',html:box,options:[]})}
function itemSheet(it){const p=G.p,d=idef(it),o=[];const eq=it===p.eq.w||it===p.eq.a;const nm=it.k==='potion'?potionLabel(it):it.k==='brew'?d.n:iname(it);if(d.k==='wpn'||d.k==='arm')o.push({label:eq?'Take off':'Equip',fn:()=>{useItem(it);return null},cls:'pri'});if(['food','drink'].includes(d.k))o.push({label:d.k==='drink'?'Drink':'Eat',fn:()=>{useItem(it);return null},cls:'pri'});if(d.k==='med'&&!d.spike)o.push({label:'Use',fn:()=>{useItem(it);return null},cls:'pri'});if(it.k==='potion'||it.k==='brew'){o.push({label:'Drink',cls:'pri',fn:()=>{drinkPotion(it);return null}});o.push({label:'Coat your weapon with it',fn:()=>{dipWeapon(it);return null}});const others=p.inv.filter(q=>q!==it&&(q.k==='potion'||q.k==='brew'));if(others.length)o.push({label:'Mix with another potion',fn:()=>({title:'Mix with which?',text:'Mixing is risky. Some combinations explode.',options:others.map(q=>({label:q.k==='potion'?potionLabel(q):idef(q).n,fn:()=>{mixPotions(it,q);return null}}))})})}if(REAGENTS.includes(it.k)&&d.k!=='food'||d.k==='herb')o.push({label:'Taste it',sub:'Learn an alchemical property',fn:()=>{tasteReagent(it);return null}});if(d.k==='scroll')o.push({label:'Study',fn:()=>{useItem(it);return null},cls:'pri'});if(d.k==='lore'||d.k==='map'||it.k==='spyglass'||it.k==='chalk'||it.k==='torch'||it.k==='suncell')o.push({label:it.k==='torch'?'Light':it.k==='spyglass'?'Look through it':it.k==='chalk'?'Draw a sigil':'Use',fn:()=>{useItem(it);return null},cls:'pri'});if(d.gun&&eq&&!p.loaded&&!d.norld)o.push({label:'Reload',fn:()=>{doReload();return null}});if(d.k==='throw'||it.k==='rawmeat'||d.bait||it.k==='potion'||it.k==='brew')o.push({label:'Throw',fn:()=>{setTarget('Tap a tile to throw '+nm.toLowerCase()+'.',(x,y)=>{if(it.k==='potion'||it.k==='brew')throwPotion(it,x,y);else doThrow(it,x,y)});return KEEP}});
 o.push({label:'Put in a quickslot',fn:()=>{p.quick=p.quick||[];const key=it.k+(it.pt||'');const i=p.quick.indexOf(key);if(i>=0)p.quick[i]=null;else{let j=p.quick.findIndex(q=>!q);if(j<0||j>3)j=(p.quick.length<4?p.quick.length:0);p.quick[j]=key}return null}});if(d.k!=='quest')o.push({label:'Drop',sub:d.meat?'Meat lures predators':'',fn:()=>{dropItem(it);return null}});showSheet({title:nm,text:describeItem(it),options:o});return KEEP}
function magicScreen(){const p=G.p,o=[];p.spells.forEach(s=>{const d=SPELLS[s];o.push({label:d.n,sub:d.mp+' mana · '+d.d,disabled:p.mp<d.mp,fn:()=>{if(d.self){playerCast(s,p.x,p.y);return null}setTarget('Tap a target for '+d.n+'.',(x,y)=>playerCast(s,x,y));return KEEP}})});p.custom.forEach(c=>{const cost=customCost(c);const self=c.fx.every(f=>EFFECTS[f.e].t==='self');o.push({label:c.name,sub:cost+' mana'+(cost>p.mp?' · pays the rest in blood':'')+' · '+c.fx.map(f=>EFFECTS[f.e].n+' '+f.mag).join(', '),fn:()=>{if(self){castCustom(c,p.x,p.y);return null}setTarget('Tap a target for '+c.name+'.',(x,y)=>castCustom(c,x,y));return KEEP}})});if(p.aug&&p.aug.cannon)o.push({label:'Arm cannon',sub:'8 sunlight charge',fn:()=>{setTarget('Tap a target for the arm cannon.',(x,y)=>fireArmCannon(x,y));return KEEP}});showSheet({title:'Magic',text:p.spells.length+p.custom.length?p.mp+' of '+p.mmp+' mana':'You know no spells yet. Find scrolls, buy them from witches and scholars, or invent your own at a spellforge.',options:o})}
function craftScreen(){const o=[];['Camp','Alchemy','Kitchen','Clothier','Smelter'].forEach(g=>{RECIPES.filter(r=>r.g===g).forEach(r=>{const need=Object.entries(r.need).map(([k,q])=>q+' '+(k==='_fish'?'fish':ITEMS[k].n.toLowerCase())).join(', ');const ok=craftAvail(r);if(!ok&&!Object.keys(r.need).some(k=>count(k)>0))return;o.push({label:g+': '+iname(mk(r.out,r.q||1)),sub:need+(r.near==='cook'?' · needs fire':r.near==='forge'?' · needs forge':''),disabled:!ok,fn:()=>{doCraft(r);refresh();craftScreen();return KEEP}})})});o.unshift({label:'Brew potions from ingredients',sub:'Combine reagents with shared hidden properties',cls:'pri',fn:()=>{brewScreen();return KEEP}});o.splice(1,0,{label:'Alchemy notebook',sub:'What you know about each ingredient',fn:()=>{notebook();return KEEP}});showSheet({title:'Craft',text:'Recipes appear when you hold an ingredient. Forge at a forge, write spells at a spellforge.',options:o})}
function notebook(){const b=el('div','char');REAGENTS.filter(k=>ITEMS[k]).forEach(k=>{const kn=G.alch.known[k]||[];b.appendChild(el('div','statrow',`<span>${esc(ITEMS[k].n)}</span><span class="small">${kn.length?kn.map(f=>APNAME[f]).join(', '):'—'}</span><b>${kn.length}/4</b>`))});b.appendChild(el('h4','','Potions known by sight'));POTS.forEach(t=>{if(G.alch.idPot[t])b.appendChild(el('p','small',cap(G.alch.looks[t])+' → '+APNAME[t]))});showSheet({title:'Alchemy notebook',html:b,options:[]})}
function brewScreen(){const p=G.p;const have=REAGENTS.filter(k=>hasItem(k));const sel=[];const box=el('div','forge');const info=el('p','preview');const grid=el('div','chips');const go=el('button','btn pri','Brew');const upd=()=>{grid.innerHTML='';have.forEach(k=>{const b=el('button','chip'+(sel.includes(k)?' on':''),esc(ITEMS[k].n)+' ×'+count(k));b.onclick=()=>{const i=sel.indexOf(k);if(i>=0)sel.splice(i,1);else if(sel.length<3)sel.push(k);upd()};grid.appendChild(b)});const known=sel.length>=2?(()=>{const c={};sel.forEach(k=>(G.alch.known[k]||[]).forEach(f=>c[f]=(c[f]||0)+1));return Object.keys(c).filter(f=>c[f]>=2)})():[];info.innerHTML=sel.length?'<b>'+sel.map(k=>esc(ITEMS[k].n)).join(' + ')+'</b><br>'+(known.length?'You expect: '+known.map(f=>APNAME[f]).join(', ')+'.':'You can\'t predict the result.')+(nearBrewing()?'':' <br>You need to be next to a fire, forge, or spellforge.')+(hasItem('flask')?'':' <br>You need an empty flask.'):'Pick two or three ingredients. Shared properties become the potion.';go.disabled=sel.length<2||!nearBrewing()||!hasItem('flask')};box.appendChild(grid);box.appendChild(info);box.appendChild(go);go.onclick=()=>{brew(sel.slice());sel.length=0;refresh();brewScreen()};upd();showSheet({title:'Brewing',text:have.length?'':'You carry no alchemical ingredients. Herbs, honey, fangs, silk, salt, pearls, dust, and more all work.',html:box,options:[]})}
function buildScreen(){const o=[];Object.entries(BUILD).forEach(([k,b])=>{const need=Object.entries(b.need).map(([m,q])=>q+' '+ITEMS[m].n.toLowerCase()).join(', ')||'Free';o.push({label:b.n,sub:need+(b.tool?' · needs '+ITEMS[b.tool].n.toLowerCase():''),disabled:!canBuild(k)||(b.tool&&!hasItem(b.tool)),fn:()=>{closeSheet();UI.build=k;setHint('Tap a tile next to you to place '+b.n.toLowerCase()+'.');refresh();return KEEP}})});showSheet({title:'Build',text:'Walls and doors make a shelter that keeps you warm. Rafts and longships let you cross the sea.',options:o})}
function forgeScreen(){const box=el('div','forge');const sel=(id,label,opts)=>{const w=el('label','fld',`<span>${label}</span>`);const s=el('select');s.id=id;Object.entries(opts).forEach(([k,v])=>{const o=el('option','',esc(v.n));o.value=k;s.appendChild(o)});w.appendChild(s);box.appendChild(w);return s};const b=sel('fb','What to make',FBASE),m=sel('fm','Material',FMAT),e=sel('fe','Enchantment',FENCH);const out=el('p','preview');box.appendChild(out);const go=el('button','btn pri','Forge it');box.appendChild(go);const upd=()=>{const B=FBASE[b.value],M=FMAT[m.value],E=FENCH[e.value],c=forgeCost(b.value,m.value,e.value);const st=B.kind==='wpn'?'Damage about '+Math.round(B.d*M.mult):'Armor about '+Math.round(B.ar*M.mult);out.innerHTML=`<b>${esc(st)}</b>${E.d?' · '+esc(E.d):''}<br>Needs ${c.matq} ${esc(ITEMS[c.mat].n.toLowerCase())} (you have ${count(c.mat)})${c.wood?', 1 wood ('+count('wood')+')':''}${c.dust?', '+c.dust+' arcane dust ('+count('dust')+')':''}`;go.disabled=!canForge(b.value,m.value,e.value)||!nearForge()};[b,m,e].forEach(s=>s.onchange=upd);upd();go.onclick=()=>{doForge(b.value,m.value,e.value);refresh();upd()};showSheet({title:'Forge',text:'Strength and practice raise the quality. Enchantments need arcane dust.',html:box,options:[]})}
function spellScreen(){const box=el('div','forge');const state={fx:[{e:'fire',mag:12,area:1,dur:0}]};const list=el('div','fxlist');box.appendChild(list);const add=el('button','btn','Add another effect');box.appendChild(add);const nm=el('label','fld','<span>Spell name</span>');const inp=el('input');inp.id='spname';inp.placeholder='Name your spell';inp.maxLength=32;nm.appendChild(inp);box.appendChild(nm);const out=el('p','preview');box.appendChild(out);const go=el('button','btn pri','Inscribe spell');box.appendChild(go);
 const upd=()=>{const c=spellCost({fx:state.fx});const dust=Math.max(1,Math.ceil(c/18));const tier=Math.min(12,1+Math.ceil(c/12));const able=G.p.st.int+G.p.lvl>=tier;out.innerHTML=`<b>${c} mana</b> per cast. You have ${G.p.mmp} max; the rest comes out of your health.<br>Costs ${dust} arcane dust (you have ${count('dust')}). ${able?'Within your skill.':'Too complex: needs Intelligence + level of '+tier+'.'}`;go.disabled=count('dust')<dust||!able||!nearSpellforge()};
 const render=()=>{list.innerHTML='';state.fx.forEach((f,i)=>{const row=el('div','fxrow');const s=el('select');s.id='sf'+i;Object.entries(EFFECTS).forEach(([k,v])=>{const o=el('option','',esc(v.n));o.value=k;if(k===f.e)o.selected=true;s.appendChild(o)});s.onchange=()=>{f.e=s.value;render();upd()};row.appendChild(s);row.appendChild(el('small','fxd',esc(EFFECTS[f.e].d)));[['mag','Magnitude',1,100],['area','Area',0,6],['dur','Duration',0,30]].forEach(([key,lb,a,b])=>{const l=el('label','rng',`<span>${lb} <b>${f[key]}</b></span>`);const r=el('input');r.type='range';r.id='sp'+key+i;r.min=a;r.max=b;r.value=f[key];r.oninput=()=>{f[key]=+r.value;l.querySelector('b').textContent=r.value;upd()};l.appendChild(r);row.appendChild(l)});if(state.fx.length>1){const x=el('button','btn sm','Remove');x.onclick=()=>{state.fx.splice(i,1);render();upd()};row.appendChild(x)}list.appendChild(row)})};render();upd();add.onclick=()=>{if(state.fx.length<4){state.fx.push({e:'sleep',mag:10,area:0,dur:5});render();upd()}};go.onclick=()=>{const sp=makeSpell(inp.value.trim(),JSON.parse(JSON.stringify(state.fx)));refresh();if(sp){closeSheet();refresh()}};showSheet({title:'Spellforge',text:'Combine up to four effects. Anything goes if you can pay for it.',html:box,options:[]})}
