function almanacScreen(){const se=seasonIdx();const b=el('div','char');b.appendChild(el('p','small',`Moon: ${MOONICON[moonPhase()]} ${moonName()}. Full moons draw out werewolves and wolves; new moons are pitch black, when thieves and vampires hunt. Roughly one full moon in five rises blood red. Rare eclipses darken midday.`));SEASONS.forEach((n,i)=>{const a=ALMANAC[i];b.appendChild(el('div','alm '+(i===se?'cur':''),`<h4>${n}${i===se?' · now':''}</h4><p class="small">${esc(a.hd)}</p><ul>${a.l.map(s=>'<li>'+esc(s)+'</li>').join('')}</ul>`))});showSheet({title:'Almanac',text:'Each season lasts '+SEASON_DAYS+' long days. A moon cycle lasts '+MOONDAYS+' days.',html:b,options:[]})}
function mapScreen(){const wrap=el('div','mapwrap');const c=document.createElement('canvas');c.className='worldmap';const base=worldMapCanvas();const step=WMAP.step;const S=2;c.width=base.width*S;c.height=base.height*S;const x=c.getContext('2d');x.imageSmoothingEnabled=false;x.drawImage(base,0,0,c.width,c.height);const fw=Math.ceil(G.W/32),fh=Math.ceil(G.H/32);const fm=document.createElement('canvas');fm.width=fw;fm.height=fh;const fx2=fm.getContext('2d');const fi=fx2.createImageData(fw,fh);for(let cy=0;cy<fh;cy++)for(let cx=0;cx<fw;cx++){const o=(cy*fw+cx)*4;fi.data[o]=8;fi.data[o+1]=10;fi.data[o+2]=16;fi.data[o+3]=G.seen.has(chunkKey(cx,cy))?0:215}fx2.putImageData(fi,0,0);x.imageSmoothingEnabled=true;x.drawImage(fm,0,0,fw*32/step*S,fh*32/step*S);x.imageSmoothingEnabled=false;x.font='600 11px "Alegreya Sans", sans-serif';x.textBaseline='middle';G.conts.filter(q=>q.real).forEach(q=>{if(![...G.seen.keys()].some(k=>{const cx=k%4096,cy=Math.floor(k/4096);return contAt(cx*32+16,cy*32+16)===q}))return;x.fillStyle='#f6efe0';x.font='400 15px "Pirata One", serif';x.fillText(q.name,(q.x-q.rx*.5)/step*S,(q.cy0+16)/step*S)});x.font='600 11px "Alegreya Sans", sans-serif';G.sites.forEach(s=>{if(!s.known)return;const px=s.x/step*S,py=s.y/step*S;x.fillStyle=s.overrun?'#e0604f':s.fac==='horde'?'#ff5a4a':s.type==='keep'?'#ffd24a':s.subking!==undefined?'#ff9a3a':'#f6efe0';x.fillRect(px-2,py-2,4,4);if(!['cave','lair','springs'].includes(s.type)){x.fillStyle='#0a0d11';x.fillText(s.name,px+5,py+1);x.fillStyle=x.fillStyle;x.fillStyle=s.fac==='horde'?'#ffb0a0':'#f6efe0';x.fillText(s.name,px+4,py)}});(G.archs||[]).forEach(a=>{if(!G.seen.has(chunkKey(a.x>>5,a.y>>5)))return;x.font='italic 400 12px "Alegreya Sans", serif';x.fillStyle='#9fd0ff';x.fillText(a.name,a.x/step*S-20,a.y/step*S-10)});x.font='600 11px "Alegreya Sans", sans-serif';G.marks.forEach(m=>{x.fillStyle='#ffd24a';x.fillText('✕ '+m.t,m.x/step*S,m.y/step*S)});(G.vessels||[]).forEach(v=>{if(v.sunk)return;x.fillStyle='#9fd0ff';x.fillRect(v.x/step*S-2,v.y/step*S-2,5,5)});const pp=L.world?G.p:(G.levels.world&&L.backTo?L.backTo:G.p);x.fillStyle='#ff3a3a';x.beginPath();x.arc(pp.x/step*S,pp.y/step*S,5,0,7);x.fill();x.strokeStyle='#fff';x.stroke();wrap.appendChild(c);showSheet({title:'World map',text:'Fog lifts where you have traveled. Ask people for directions to mark more places.',html:wrap,options:[]});setTimeout(()=>{wrap.scrollLeft=pp.x/step*S-wrap.clientWidth/2;wrap.scrollTop=pp.y/step*S-wrap.clientHeight/2},30)}
function helpScreen(){const b=el('div','char',`<h4>Moving</h4><p class="small">Tap a far tile to walk there, or use the pad. Tap anything else to see what you can do with it; long-press or right-click for every option. Keyboard: arrows, numpad, or hjklyubn; Space for your own tile; . to wait; +/- to zoom; F to fish.</p><h4>Goal</h4><p class="small">Vorgath rules from a sealed keep on his own continent. Each other continent has a sub-king holding a shard of the seal. Each sub-king has a weakness: pride, greed, fear, faith, hunger, riddles, drink, sickness, paranoia, or secret rebellion. Ask locals about the sub-king to learn it, then win his shard however you like. Every shard, and the ending, can be won without killing anyone.</p><h4>Crossing the sea</h4><p class="small">Book passage at a port, or build a raft or buy a longship. Steer onto water to sail and into land to step ashore. Fit cannons for pirates and sea monsters. Fish from the deck.</p><h4>The world lives without you</h4><p class="small">Armies march along roads and lay siege to towns. Nations fight back. Caravans trade, herds migrate, pirates raid coasts, monsters roam, and plagues spread from village to village. Everything you hear in "What news?" really happened somewhere.</p><h4>Checks</h4><p class="small">Risky actions roll a d20 against a difficulty, and the result appears in your log. Heroic moments grant inspiration, which rerolls your next failure. Independent creatures roll 2d6 to react when they first meet you; wounded and leaderless enemies may break and flee, or surrender.</p><h4>Body</h4><p class="small">Watch food, water, temperature, and disease. Diseases incubate silently, then show symptoms; healers can diagnose them. Vampirism and moon-blood can be cured. Solar augments make you strong but need sunlight.</p><h4>Alchemy</h4><p class="small">Every ingredient has four hidden properties, different every world. Taste ingredients to learn them; brew two or three together and the shared properties become your potion. Found potions are unidentified: drink, throw, or have them identified.</p>`);showSheet({title:'How to play',html:b,options:[]})}
function settingsScreen(){showSheet({title:'Settings',options:[{label:'Music: '+(AU.music?'on':'off'),fn:()=>{AU.music=!AU.music;saveSettings();settingsScreen();return KEEP}},{label:'Sound effects: '+(AU.sfx?'on':'off'),fn:()=>{AU.sfx=!AU.sfx;saveSettings();settingsScreen();return KEEP}},{label:'Volume: '+Math.round(AU.vol*100)+'%',sub:'Tap to cycle',fn:()=>{AU.vol=AU.vol>=1?.25:AU.vol+.25;if(AU.master)AU.master.gain.value=AU.vol;saveSettings();settingsScreen();return KEEP}},{label:'Direction pad: '+(UI.dpad?'shown':'hidden'),fn:()=>{UI.dpad=!UI.dpad;applyDpad();saveSettings();settingsScreen();return KEEP}},{label:'Minimap: '+(UI.mini?'shown':'hidden'),fn:()=>{UI.mini=!UI.mini;saveSettings();sizeMap();settingsScreen();return KEEP}}]})}
function applyDpad(){$('#game').classList.toggle('nodpad',!UI.dpad)}
function devScreen(){const o=[];const k=()=>KEEP;o.push({label:'Reveal this continent',fn:()=>{const c=contAt(G.p.x,G.p.y)||G.conts[G.startCont];for(let cy=c.cy0>>5;cy<(c.cy0+(c.ch||CELL))>>5;cy++)for(let cx=c.cx0>>5;cx<(c.cx0+(c.cw||CELL))>>5;cx++){const key=chunkKey(cx,cy);if(!G.seen.has(key))G.seen.set(key,new Uint8Array(1024).fill(1))}G.sites.filter(s=>s.cont===c.id).forEach(s=>s.known=1);msg('Revealed.','hint');return null}});o.push({label:'Full health, food, mana, cure all',fn:()=>{const p=G.p;p.hp=p.mh;p.mp=p.mmp;p.hunger=100;p.thirst=100;p.dz=[];p.temp=0;return null}});o.push({label:'Skip to next season',sub:'Now '+seasonName(),fn:()=>{G.turn=(Math.floor(G.turn/SEASON)+1)*SEASON;seasonTick();realizeTick(true);computeFOV();return null}});o.push({label:'Skip to night',fn:()=>{G.turn=Math.floor(G.turn/DAY)*DAY+Math.round(DAY*.76);computeFOV();return null}});o.push({label:'Skip to the next full moon',fn:()=>{const d=Math.floor(G.turn/DAY);let n=d+1;while(n%MOONDAYS!==4)n++;G.turn=n*DAY+Math.round(DAY*.78);moonTick();computeFOV();return null}});o.push({label:'Give supplies',sub:'Metal, dust, wood, food, bombs, rope, gold, gears',fn:()=>{[['iron',6],['steel',4],['stariron',4],['dust',16],['wood',50],['cooked',6],['water',4],['rope',8],['firebomb',2],['powder',2],['sleepbomb',2],['pelt',6],['stoneblock',8],['tonic',2],['shot',10],['sleepdraught',2],['coins',800],['gear',4],['relic',1],['forgedorders',1],['flask',4],['bloodmoss',3],['sunleaf',3],['honey',2]].forEach(([k,q])=>giveItem(mk(k,q),true));msg('Supplies added.','hint');return null}});o.push({label:'Grant all shards but one',fn:()=>{G.conts.filter(c=>c.real&&c.id!==G.kingCont).slice(1).forEach(c=>{if(G.subkings[c.id])G.subkings[c.id].shard=0;giveItem(Object.assign(mk('shard'),{cont:c.id}))});return null}});o.push({label:'Spawn a raft beside you',fn:()=>{const w=waterSpot(G.p.x,G.p.y,8);if(w)newVessel('raft',w.x,w.y,'p');else msg('No water nearby.','warn');return null}});o.push({label:'Spawn a longship beside you',fn:()=>{const w=waterSpot(G.p.x,G.p.y,8);if(w){const v=newVessel('longship',w.x,w.y,'p');v.cannons=2;v.hold.push(mk('cannonball',12))}else msg('No water nearby.','warn');return null}});o.push({label:'Spawn a vehicle beside you',sub:'Pick any of '+Object.keys(VEH).length,fn:()=>({title:'Spawn a vehicle',options:Object.keys(VEH).map(k=>({label:cap(VEH[k].n),sub:VEH[k].d,fn:()=>{const sp=VEH[k].terr==='water'?waterSpot(G.p.x,G.p.y,10):landSpotFor(k,G.p.x,G.p.y,8);if(!sp){msg('No suitable ground nearby.','warn');return null}const v=newVessel(k,sp.x,sp.y,'p',{pull:VEH[k].power==='animal'?'horse':null,fuel:VEH[k].power==='solar'?100:6,cannons:VEH[k].cannons?2:0});if(VEH[k].wpn&&VEH[k].wpn.ammo)v.hold.push(mk(VEH[k].wpn.ammo,12));if(VEH[k].cannons)v.hold.push(mk('cannonball',12));msg('A '+VEH[k].n+' appears.','hint');return null}}))})});o.push({label:'Teleport to an island',fn:()=>({title:'Islands',options:G.sites.filter(s=>s.isle!==undefined).slice(0,30).map(s=>({label:s.name,sub:s.type+' · '+G.archs[s.isle].name,fn:()=>{abstractAll();if(!L.world){L=G.levels.world;G.p.lv='world'}const sp=passableSpot(s.x,s.y,s.r+3);if(sp){G.p.x=sp.x;G.p.y=sp.y;G.p.aboard=null;s.known=1;realizeTick(true);computeFOV()}return null}}))})});o.push({label:'Summon a warhorse',fn:()=>{const q=passableSpot(G.p.x,G.p.y,3);if(q)spawn('warhorse',q.x,q.y,{tame:1,stay:1,wild:1});return null}});o.push({label:'Start a Black Boil outbreak nearby',fn:()=>{RT.act.filter(c=>SP[c.s].tags.person).slice(0,3).forEach(c=>{c.dz='boil';c.dzT=300});return null}});o.push({label:'Start the Grey Walk nearby',fn:()=>{const n=RT.act.filter(c=>SP[c.s].tags.person);if(n.length){n[0].dz='zombie';n[0].dzT=12;G.flags.grey=G.turn}return null}});o.push({label:'Become a vampire',fn:()=>{G.p.dz.push({k:'vampire',t:999999,inc:0,known:true});return null}});o.push({label:'Install all augments',fn:()=>{Object.keys(AUGS).forEach(installAug);G.p.charge=100;return null}});o.push({label:'Send a Horde warband here',fn:()=>{const b=newBand('warband','horde',G.p.x+20,G.p.y,[{s:'captain',lead:true},{s:'horde'},{s:'berserker'},{s:'hrider',mount:mountRec('bigwolf')},{s:'hrider',mount:mountRec('warelephant')}],{});b.goal={x:G.p.x,y:G.p.y};return null}});o.push({label:'Send a plague swarm here',fn:()=>{const b=newBand('swarm','plague',clamp(G.p.x+18,2,G.W-3),G.p.y,Array(20).fill(0).map((_,i)=>({s:'zombie',lead:i===0})),{});b.goal={x:G.p.x,y:G.p.y};return null}});G.sites.filter(s=>['keep','citadel','town','port','vault','witch','vlair'].includes(s.type)).slice(0,40).forEach(s=>o.push({label:'Teleport: '+s.name,sub:s.type+' · '+G.conts[s.cont].name,fn:()=>{if(!L.world){abstractAll();L=G.levels.world;G.p.lv='world'}abstractAll();const sp=passableSpot(s.x,s.y+s.r+2,10)||passableSpot(s.x,s.y,14);if(sp){G.p.x=sp.x;G.p.y=sp.y;G.p.aboard=null;s.known=1;realizeTick(true);computeFOV()}return null}}));showSheet({title:'Demo tools',text:'For showing the game off. They work on your current run.',options:o})}
function showEnd(){const o=G.over;const e=ENDINGS[o.kind]||ENDINGS.death;const s=G.stats;const top=G.story.filter(x=>x.w>0).sort((a,b)=>b.w-a.w).slice(0,8).sort((a,b)=>a.turn-b.turn);$('#game').hidden=true;$('#end').hidden=false;sfx(o.kind==='death'?'death':'level');const blood=s.killsP===0&&s.killsA===0?'Bloodless: you took no life at all.':s.killsP===0?'Clean hands: you killed no person.':`You killed ${s.killsP} ${s.killsP===1?'person':'people'}.`;$('#end').innerHTML=`<div class="endin"><p class="eyebrow">${o.kind==='death'?'Permadeath':'An ending'}</p><h1>${esc(e.t)}</h1><p class="lead">${esc(o.kind==='death'?G.p.name+' died to '+o.by+' in '+seasonName()+', year '+yearNum()+'.':e.d)}</p><p class="rate">${esc(blood)}</p><h3>The story of your run</h3><ol>${top.map(t=>`<li><small>${esc(t.season)}</small> ${esc(t.t)}</li>`).join('')||'<li>Nothing anyone will remember.</li>'}</ol><dl><dt>Days survived</dt><dd>${Math.floor(G.turn/DAY)}</dd><dt>Level</dt><dd>${G.p.lvl}</dd><dt>Shards</dt><dd>${G.flags.shardsGot||0}</dd><dt>People killed</dt><dd>${s.killsP}</dd><dt>Spared</dt><dd>${s.spared||0}</dd><dt>World seed</dt><dd>${G.seed}</dd></dl><button id="again" class="btn pri big">Play again</button></div>`;$('#again').onclick=()=>{G=null;$('#end').hidden=true;titleScreen()}}
// ---- title / creation
function previewMap(){const c=$('#tcv');if(!c)return;const save=G,saveL=L;const sd=(Date.now()%999999)+1;G={rs:sd,cid:0,turn:0,flags:{}};setupWorld(sd,{conts:8});const step=8;const w=G.W/step,h=G.H/step;c.width=w;c.height=h;const x=c.getContext('2d');const draw2=s2=>{const img=x.createImageData(w,h);for(let j=0;j<h;j++)for(let i=0;i<w;i++){const tb=terrainAt(i*step,j*step);const col=tileColor(TN[tb&255],BIOMES[tb>>8][0],s2);const n=parseInt(col.slice(1),16);const o=(j*w+i)*4;img.data[o]=n>>16;img.data[o+1]=(n>>8)&255;img.data[o+2]=n&255;img.data[o+3]=255}x.putImageData(img,0,0)};const snap=Object.assign({},G);let s2=0;draw2(0);G=save;L=saveL;clearInterval(UI.tt);if(!reduced())UI.tt=setInterval(()=>{if(!$('#tcv')||$('#title').hidden){clearInterval(UI.tt);return}s2=(s2+1)%4;const sv=G,sl=L;G=snap;CELL=320;draw2(s2);G=sv;L=sl;document.documentElement.dataset.season=s2;const l=$('#tseason');if(l)l.textContent=SEASONS[s2]},2800)}
function titleScreen(){$('#game').hidden=true;$('#end').hidden=true;$('#create').hidden=true;$('#title').hidden=false;loadSaveStr().then(s=>{$('#contbtn').hidden=!s;UI.saveStr=s});previewMap()}
const WOPTS=[['style','Map style',[['earth','Earthlike world map'],['classic','Classic (continents on a grid)']]],['scale','World scale',[['standard','Standard (smaller, quicker to cross)'],['vast','Vast (the default: 2.25× Standard)'],['colossal','Colossal (4× Standard)'],['titanic','Titanic (6× Standard; needs a fast device)']],'vast'],['conts','Continents',[[6,'6'],[7,'7'],[8,'8'],[9,'9'],[10,'10']],8],['sea','Sea level',[[-.08,'Low (bigger land)'],[0,'Normal'],[.07,'High (smaller land)']],0],['temp','Climate',[[-.15,'Ice age'],[-.06,'Cold'],[0,'Temperate'],[.07,'Warm'],[.15,'Hothouse']],0],['moist','Rainfall',[[-.15,'Arid'],[0,'Normal'],[.15,'Wet']],0],['rivers','Rivers',[[.5,'Few'],[1,'Normal'],[1.6,'Many']],1],['islands','Islands',[[0,'Few'],[1,'Normal'],[2.5,'Many']],1],['nations','Nations per continent',[[1,'Few'],[2,'Normal'],[3,'Many']],2],['horde','Horde strength',[[.6,'Weak'],[1,'Normal'],[1.6,'Overwhelming']],1],['monsters','Monsters',[[.5,'Rare'],[1,'Normal'],[2,'Infested']],1],['wildlife','Wildlife',[[.5,'Sparse'],[1,'Normal'],[1.8,'Teeming']],1],['ruins','Ruins and tombs',[[.5,'Few'],[1,'Normal'],[2,'Many']],1],['history','History length',[[80,'80 years'],[200,'200 years'],[500,'500 years']],200]];
function createScreen(){$('#title').hidden=true;$('#create').hidden=false;UI.pick=UI.pick||'mage';UI.bg=UI.bg||'outlander';const list=$('#classes');list.innerHTML='';Object.entries(CLASSES).forEach(([k,c])=>{const b=el('button','classcard'+(k===UI.pick?' sel':''));b.innerHTML=`<h3>${esc(c.n)}</h3><p>${esc(c.d)}</p><div class="cstats">${Object.keys(STATN).map(s=>`<span title="${STATN[s]}">${STATN[s].slice(0,3)} <b>${c.st[s]}</b></span>`).join('')}</div>`;b.onclick=()=>{UI.pick=k;createScreen()};list.appendChild(b)});const bl=$('#bgs');bl.innerHTML='';Object.entries(BACKGROUNDS).forEach(([k,b])=>{const e=el('button','chip'+(k===UI.bg?' on':''),esc(b.n));e.title=b.d;e.onclick=()=>{UI.bg=k;createScreen()};bl.appendChild(e)});$('#bgdesc').textContent=BACKGROUNDS[UI.bg].d;const wo=$('#wopts');if(!wo.childElementCount){WOPTS.forEach(([k,lab,vals,def])=>{const w=el('label','fld',`<span>${lab}</span>`);const s=el('select');s.id='wo_'+k;vals.forEach(([v,t])=>{const o=el('option','',esc(t));o.value=v;if(def!==undefined&&String(v)===String(def))o.selected=true;s.appendChild(o)});w.appendChild(s);wo.appendChild(w)})}}
function readOpts(){const o={};WOPTS.forEach(([k,,vals])=>{const v=$('#wo_'+k).value;o[k]=isNaN(+v)?v:+v});return o}
function beginGame(){const name=$('#pname').value.trim()||pickName();const seedV=$('#pseed').value.trim();let seed;if(seedV==='daily'){const d=new Date();seed=d.getFullYear()*372+d.getMonth()*31+d.getDate()}else if(seedV){seed=0;for(const ch of seedV)seed=(seed*31+ch.charCodeAt(0))|0;seed=Math.abs(seed)||1}$('#create').hidden=true;$('#loading').hidden=false;setTimeout(()=>{newGame({cls:UI.pick,name,seed,opt:readOpts()});applyBackground(UI.bg);SPRC.player=null;delete SPRC['player|'];$('#loading').hidden=true;$('#game').hidden=false;applyDpad();sizeMap();saveGame();refresh()},30)}
function pickName(){const a=(['Ansa','Bram','Corvin','Dessa','Edda','Fenn','Galen','Hale','Isolde','Jory','Kes','Lark','Maren','Nell','Orrin','Pell','Quill','Rook','Sable','Tamsin','Una','Wren']);return a[Math.floor(Math.random()*a.length)]}
function continueGame(){$('#title').hidden=true;$('#loading').hidden=false;setTimeout(()=>{try{deserial(UI.saveStr);delete SPRC['player|'];$('#loading').hidden=true;$('#game').hidden=false;applyDpad();sizeMap();msg('Welcome back.','hint');refresh()}catch(e){console.error(e);$('#loading').hidden=true;$('#title').hidden=false;alert('Save could not be loaded.')}},30)}
function tickFrame(){UI.frame++;if(G&&G.p&&$('#game')&&!$('#game').hidden&&!G.over){draw();if(UI.frame%6===0)musicTick()}else if(UI.frame%6===0&&AU.on&&$('#title')&&!$('#title').hidden)musicTick()}
function start(data){UI.reducedM=reduced();UI.mini=true;loadSettings();bindMap();bindControls();$('#newbtn').onclick=()=>{audioInit();createScreen()};$('#contbtn').onclick=()=>{audioInit();continueGame()};$('#backbtn').onclick=titleScreen;$('#beginbtn').onclick=beginGame;$('#dailybtn').onclick=()=>{$('#pseed').value='daily'};addEventListener('resize',sizeMap);addEventListener('pagehide',saveGame);document.addEventListener('visibilitychange',()=>{if(document.hidden)saveGame()});setInterval(tickFrame,160);if(document.fonts&&document.fonts.load)document.fonts.load('700 20px "Pixelify Sans"').then(()=>draw()).catch(()=>{});
 window.claude?.hot?.snapshot?.(()=>({save:G&&G.p&&!G.over?serial():null}));if(data&&data.save){try{deserial(data.save);$('#title').hidden=true;$('#game').hidden=false;applyDpad();sizeMap();refresh();return}catch(e){}}titleScreen()}
window.claude?.hot?.ready?window.claude.hot.ready(start):start(window.claude?.hot?.data??{});
if('serviceWorker' in navigator&&/^https?:$/.test(location.protocol)&&!window.claude)navigator.serviceWorker.register('sw.js').catch(()=>{});
